<?php require_once '../config/auth.php';requireLogin();require_once '../config/database.php';$livros=$conn->query("SELECT id,titulo,quantidade_disponivel FROM livros WHERE quantidade_disponivel>0 ORDER BY titulo");$users=$conn->query("SELECT id,nome FROM utilizadores ORDER BY nome");if($_SERVER['REQUEST_METHOD']==='POST'){$livro=(int)$_POST['livro_id'];$user=(int)$_POST['utilizador_id'];$prev=$_POST['data_prevista'];$hoje=date('Y-m-d');$s=$conn->prepare("INSERT INTO emprestimos(livro_id,utilizador_id,data_emprestimo,data_prevista) VALUES(?,?,?,?)");$s->bind_param('iiss',$livro,$user,$hoje,$prev);$s->execute();$s=$conn->prepare("UPDATE livros SET quantidade_disponivel=quantidade_disponivel-1 WHERE id=? AND quantidade_disponivel>0");$s->bind_param('i',$livro);$s->execute();header('Location: index.php');exit;}?><!doctype html><html lang="pt"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Novo empréstimo</title><link rel="stylesheet" href="../assets/css/style.css"></head><body><div class="container"><div class="card"><h1>Novo empréstimo</h1><form method="post"><label>Livro</label><select name="livro_id" required><?php while($l=$livros->fetch_assoc()):?><option value="<?=$l['id']?>"><?=$l['titulo']?> (<?=$l['quantidade_disponivel']?> disponível)</option><?php endwhile;?></select><label>Utilizador</label><select name="utilizador_id" required><?php while($u=$users->fetch_assoc()):?><option value="<?=$u['id']?>"><?=$u['nome']?></option><?php endwhile;?></select><label>Data prevista</label><input type="date" name="data_prevista" required><button>Registar</button></form></div></div></body></html>
